function startRoom()
{
   roomfunctionality.init();
}
var roomfunctionality = new com.clubpenguin.world.rooms.StadiumIceRink(this);
var wem = new com.clubpenguin.world.rooms.weathereffects.WeatherEffectsManager(SHELL,background_mc);
wem.setupFireAnimationHeight(35);
wem.setupRainAnimationHeight(50);
wem.setupSnowAnimationHeight(50);
wem.setupRainAnimationSpeed(0.4);
wem.setupSnowAnimationSpeed(0.8);
wem.setupRainDelayTime(1.5);
